head.script:
scwin.screenId = "jldfil35715";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존 순서로 순차 호출한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 화면 전환 파라미터 수신 (kk 확보)
        scwin.init_conds(); // 2) kk 값 기준 수수료 문구 표시 조건 평가
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35715.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 팝업 유형 파라미터(dma_pageContext.kk) 값에 따라 건당 수수료 문구(if_kk_3_txt·if_kk_4_txt)의 표시 여부를 평가한다(공용 $c.util.evalConds, 진입점에서 1회 호출).
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function () {
    const kk = $c.data.readValue("dma_pageContext", "kk", { ctx: true, label: "param.kk" });
    const binds = [{
        id: "if_kk_3_txt",
        fn: function () { return kk === 3; }
    }, {
        id: "if_kk_4_txt",
        fn: function () { return kk === 4; }
    }];
    $c.util.evalConds(binds);
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_self_onclick
 * @description [닫기] 버튼 클릭 — 현재 수수료 계산원칙 팝업을 닫는다($c.win.closePopup).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_self ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_self_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil35715.btn_self_onclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////
